from xml.etree import ElementTree as ET

def xml_items(text):
    return None

lessons.solution:
from xml.etree import ElementTree as ET
def xml_items(text):
    root=ET.fromstring(text)
    if root.tag!='items': raise ValueError('expected items root')
    result=[]
    for item in root.findall('item'):
        if 'id' not in item.attrib: raise ValueError('missing id')
        result.append((int(item.attrib['id']),(item.text or '').strip()))
    return result

checks.code:
def _bad(call, error=ValueError):
    try:
        call()
    except error:
        return True
    return False
assert _bad(lambda: xml_items('<other/>'))
assert _bad(lambda: xml_items('<items><item/></items>'))

