    return None

def unzip_texts(blob):
    return None

lessons.solution:
import io
import zipfile
def zip_texts(entries):
    buffer=io.BytesIO()
    with zipfile.ZipFile(buffer,'w') as archive:
        for name,text in entries.items():
            archive.writestr(name,text.encode('utf-8'))
    return buffer.getvalue()
def unzip_texts(blob):
    with zipfile.ZipFile(io.BytesIO(blob)) as archive:
        return {item.filename:archive.read(item).decode('utf-8') for item in archive.infolist() if not item.is_dir()}

