import gzip

import json

def pack_json(value):
    return None

def unpack_json(blob):
    return None

lessons.solution:
import gzip
import json
def pack_json(value):
    raw=json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode('utf-8')
    return gzip.compress(raw,mtime=0)
def unpack_json(blob):
    return json.loads(gzip.decompress(blob).decode('utf-8'))

